$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Speech
$mediaDirectory = Join-Path $PSScriptRoot '../public/media'
$null = New-Item -ItemType Directory -Path $mediaDirectory -Force
$synthesizer = New-Object System.Speech.Synthesis.SpeechSynthesizer
$synthesizer.Rate = -1
$guides = @{
  'mindful-pause' = @'
<speak version="1.0" xml:lang="en-US">Welcome to a small pause in your day. There is nothing you need to achieve in this moment. Find a position that feels comfortable. You can sit, stand, or lie down. Keep your eyes open, or gently lower your gaze. <break time="3s"/> Notice where your body meets the chair or the floor. Let your hands rest. You do not need to change your breathing. Simply notice one breath coming in, and one breath going out. <break time="5s"/> If paying attention to your breathing feels uncomfortable, choose a sound in the room or the feeling of your feet on the floor. Any steady point of attention is fine. <break time="5s"/> Thoughts may arrive. That is an ordinary part of being human. Notice the thought, and gently bring your attention back to the place you have chosen. You can begin again as often as you need. <break time="5s"/> Now notice three things you can see. A color. An edge. A patch of light. Take your time. <break time="5s"/> Notice two sounds, near or far. There is no need to name them perfectly. Simply listen. <break time="5s"/> Notice one point of contact with the surface supporting you. Let that be enough for this moment. <break time="5s"/> Ask yourself: what would be a kind, useful next step? It might be a glass of water, a stretch, a message to someone you trust, or returning to one small task. <break time="5s"/> When you are ready, look around the room. Move your hands or feet gently. Take your next step at your own pace. You can return to this practice whenever it is useful, and pause or stop whenever you prefer.</speak>
'@
  'focus-session' = @'
<speak version="1.0" xml:lang="en-US">Welcome. This short guide will help you prepare for a focused work session. Before you begin, make a little space on your desk. Keep what you need and move one unnecessary distraction out of reach. <break time="4s"/> Take a moment to look at your task list. Choose one task that would make today a little easier or more meaningful. You do not need to choose the biggest task. Choose something you can begin. <break time="5s"/> Write down a clear outcome for the next twenty five minutes. For example: outline three points for a presentation, or read and summarize two pages. Keep the outcome specific and realistic. <break time="5s"/> Now write the first physical action. Open the document. Find the page. Write the heading. The smaller this first step is, the easier it can be to start. <break time="5s"/> Check whether you have what you need. Water, your notes, and the right tools. Silence notifications that can wait. If someone may need to reach you urgently, leave an appropriate channel available. <break time="4s"/> You may notice an urge to check another task. Keep a piece of paper nearby. When a new thought arrives, write a short reminder and return to your chosen task. You can review the reminder later. <break time="5s"/> Set a timer for a length of time that works for you. Twenty five minutes is one option. Ten minutes can be a useful beginning too. This is an experiment in attention, not a test of discipline. <break time="4s"/> After your session, stand up or change position if that feels comfortable. Notice what you accomplished and what made starting easier. Decide whether to continue, take a break, or adjust the plan. <break time="3s"/> Your next step is ready. Start the timer, and begin the first small action.</speak>
'@
  'wind-down' = @'
<speak version="1.0" xml:lang="en-US">Let this be a gentle transition into your evening. You do not need to finish every task before you are allowed to rest. Find a comfortable place and bring a notebook or a piece of paper nearby. <break time="4s"/> Start by noticing what is still on your mind. An unfinished task, a message to send, or something you want to remember. Write each thought as a short note. You do not need to solve it now. <break time="5s"/> Choose one item that needs attention tomorrow. Beside it, write the smallest next action. If an item can wait, let it stay on the page. The page can hold the reminder for you. <break time="5s"/> Now think about your morning. Is there one simple preparation that would make it easier? Put out comfortable clothes, prepare a bag, or place a glass of water nearby. Choose just one thing if it is useful. <break time="5s"/> Consider the space around you. Could you lower a bright light or reduce a little noise? Make a small adjustment if it feels good. A comfortable evening does not require a perfect room. <break time="4s"/> Notice your breathing without trying to change it. Feel the surface supporting you. If you prefer, simply look at a familiar object in the room. <break time="5s"/> Think of one ordinary thing you appreciated today. A conversation, a meal, a quiet minute, or finishing something small. Difficult days can contain small moments of relief too. You do not have to force a positive feeling. <break time="5s"/> Choose a quiet activity for the next few minutes. Reading, gentle stretching, or listening to something familiar may help you settle. Let your choice fit your own preferences. <break time="4s"/> You are allowed to pause. Tomorrow can have its own beginning. If sleep difficulties continue or affect your daily life, seek advice from a qualified health professional. For now, take the evening one gentle step at a time.</speak>
'@
}
$transcripts = @{}
try {
  foreach ($guide in $guides.GetEnumerator()) {
    $outputPath = [IO.Path]::GetFullPath((Join-Path $mediaDirectory ($guide.Key + '.wav')))
    $synthesizer.SetOutputToWaveFile($outputPath)
    $synthesizer.SpeakSsml($guide.Value)
    $synthesizer.SetOutputToNull()
    $transcripts[$guide.Key] = ([regex]::Replace($guide.Value, '<[^>]+>', ' ') -replace '\s+', ' ').Trim()
    Write-Output ('Generated ' + $guide.Key)
  }
  $transcriptsPath = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../src/lib/transcripts.json'))
  [IO.File]::WriteAllText($transcriptsPath, ($transcripts | ConvertTo-Json), (New-Object Text.UTF8Encoding($false)))
} finally { $synthesizer.Dispose() }
